CREATE OR REPLACE PROCEDURE PivotProducts()
LANGUAGE plpgsql AS $$
DECLARE
    sql_query TEXT;
BEGIN
    SELECT 'SELECT product_id, ' ||
           STRING_AGG(DISTINCT 'MAX(CASE WHEN store = ''' || store || ''' THEN price END) AS ' || quote_ident(store), ', ' ORDER BY store) ||
           ' FROM Products GROUP BY product_id'
    INTO sql_query
    FROM Products;
    EXECUTE sql_query;
END;
$$;
